import{_ as s,a0 as i,w as p,s as d,ao as l,I as n,x as t,a1 as a,A as e}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const b=JSON.parse('{"title":"瞭解如何使用 Norka 編輯器閲讀文本 | LCTT x X-CMD","titleTemplate":false,"description":"瞭解如何使用 Norka 編輯器閲讀文本 | LCTT (202012) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"瞭解如何使用 Norka 編輯器閲讀文本 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"瞭解如何使用 Norka 編輯器閲讀文本 | LCTT (202012) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202012/20201218 Find out how your text will be read with Norka","title":"瞭解如何使用 Norka 編輯器閲讀文本","tag":"202012","desc":""},"relativePath":"202012/20201218 Find out how your text will be read with Norka.md","filePath":"[post].md"}'),k={name:"202012/20201218 Find out how your text will be read with Norka.md"};function u(m,o,N,f,T,h){const r=i("Link");return p(),d("div",null,[o[23]||(o[23]=l('<h1 id="瞭解如何使用-norka-編輯器閲讀文本" tabindex="-1">瞭解如何使用 Norka 編輯器閲讀文本 <a class="header-anchor" href="#瞭解如何使用-norka-編輯器閲讀文本" aria-label="Permalink to “瞭解如何使用 Norka 編輯器閲讀文本”">​</a></h1><blockquote><p>這是一個素顏朝天的文本編輯器，旨在讓你的寫作能被更好地閲讀和理解。</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/202012/28/003505f3h3pppkg7enpxi9.jpg" alt=""></p><p>有些文本編輯器是為編程而設計的，有些是為專門的文本格式而設計的，有些是為文檔設計而設計的。Norka 文本編輯器是為閲讀而設計的。創建一個為<em>閲讀</em>而設計的文本編輯器似乎很奇怪，但實際上，如果你仔細想想，這是很有意義的。你的文字已經寫了一次或三次，這取決於你個人對迭代的容忍度，但它的目的是為了在未來幾年內被閲讀。Norka 讓你輕鬆地專注於你的文字如何被閲讀。</p><h3 id="安裝" tabindex="-1">安裝 <a class="header-anchor" href="#安裝" aria-label="Permalink to “安裝”">​</a></h3>',5)),n("p",null,[o[2]||(o[2]=t("Norka 文本編輯器是 MIT 授權的，可以",-1)),a(r,{href:"https://flathub.org/apps/details/com.github.tenderowl.norka"},{default:e(()=>[...o[0]||(o[0]=[t("作為 Flatpak 包安裝在 Linux上",-1)])]),_:1}),o[3]||(o[3]=t("。它是開源的，所以如果你想嘗試在不同的平台上安裝它，你可以",-1)),a(r,{href:"https://github.com/TenderOwl/Norka"},{default:e(()=>[...o[1]||(o[1]=[t("克隆它的 Github 倉庫",-1)])]),_:1}),o[4]||(o[4]=t("。",-1))]),o[24]||(o[24]=l('<h3 id="norka-的界面" tabindex="-1">Norka 的界面 <a class="header-anchor" href="#norka-的界面" aria-label="Permalink to “Norka 的界面”">​</a></h3><p>Norka 的界面很簡單。一個回到 Norka 文檔集的按鈕，一個導出按鈕和一個偏好菜單。窗口的其餘部分是供你寫文字的空白空間，在右下角，有一個閲讀時間計算器來幫助你瞭解讀者可能需要多長時間才能看完你寫的東西。</p><p><img src="https://opensource.com/sites/default/files/uploads/norka-31_days-norka-opensource.png" alt="Dark Norka terminal box with green and white text" title="Dark Norka terminal box with green and white text"></p><p>這幾乎就是 Norka 的全部內容。沒有分頁符或行號，沒有代碼摺疊或正則搜索。這是一個用於文字書寫的編輯器，而不設置文檔樣式或跟蹤複雜的數據模式。</p><p>當然，它還有一些額外的功能。如預期那樣，可以使用 <code>Ctrl+C</code> 和 <code>Ctrl+V</code> 複製和粘貼。你可以用 <code>Ctrl+Z</code> 撤銷，用 <code>Ctrl+F</code> 查找。你甚至可以用 <code>Ctrl+:</code> 插入表情符號。</p><p><img src="https://opensource.com/sites/default/files/uploads/norka_emoji-31_days-norka-opensource.png" alt="Norka terminal box with pop up box of emoji search menu" title="Norka terminal box with pop up box of emoji search menu"></p><h4 id="樣式文本" tabindex="-1">樣式文本 <a class="header-anchor" href="#樣式文本" aria-label="Permalink to “樣式文本”">​</a></h4>',7)),n("p",null,[o[6]||(o[6]=t("雖然 Norka 絕對沒有興趣幫你設計，比如説，一本小冊子或傳單，但它確實有一些能力來指示你想要的文本樣式。它通過 ",-1)),a(r,{href:"https://opensource.com/article/19/9/introduction-markdown"},{default:e(()=>[...o[5]||(o[5]=[t("Markdown",-1)])]),_:1}),o[7]||(o[7]=t(" 來實現這一點，這是一個簡單的純文本書寫的約定，但用特殊的符號來指示文本應該如何在 HTML、EPUB 或 PDF 或任何你的目標格式中呈現。",-1))]),o[25]||(o[25]=l('<p>在大多數編輯器中，你必須知道 Markdown 才能使用 Markdown，但 Norka 翻譯了常見的文字處理器鍵盤快捷鍵來為你生成 Markdown。例如，要使一個單詞加粗，你可以按 <code>Ctrl+B</code>，它會在光標的兩邊插入四個星號。當你輸入下一個單詞時，它的兩邊都會有兩個星號，這就是 Markdown 對粗體（默認為粗體）文本的標記。你可以在 Norka 窗口右上角的漢堡樣式的菜單中查看所有的 Markdown 快捷方式。</p><h4 id="保存和導出" tabindex="-1">保存和導出 <a class="header-anchor" href="#保存和導出" aria-label="Permalink to “保存和導出”">​</a></h4><p>你可以把 Norka 想像成一個筆記本。你在 Norka 中打開的所有文檔都會保留在 Norka 的內部資料庫中，所有的文檔都會默認自動保存。要在 Norka 外使用文件，你可以在打開的文件中點擊右上角的<strong>共享</strong>按鈕。另外，你也可以在 Norka 的文件視圖中右擊任何文件，選擇<strong>導出</strong>。你可以將文檔導出（或<strong>共享</strong>，Norka 可互換使用這兩個術語）為<strong>文本</strong>、<strong>HTML</strong> 或 <strong>Markdown</strong>。</p><h3 id="嘗試-norka" tabindex="-1">嘗試 Norka <a class="header-anchor" href="#嘗試-norka" aria-label="Permalink to “嘗試 Norka”">​</a></h3><p>Norka 便於嘗試，也易於使用。它通過保持界面簡單，幾乎到了受限的程度，幫助你專注於寫作。但限制有時也是一種強大的創意工具。</p><p>Norka 可能不是你進行大量修改或文本處理的最佳選擇。它沒有讓人激動的功能，比如大小寫轉換、集成 <code>sed</code> 命令、字符交換等等。它是一個為讀者服務的文本編輯器。如果你覺得有用，那麼你可能正是 Norka 正在尋找的受眾。</p><p>感謝你花 2 分 39 秒閲讀本文！</p><hr>',8)),n("p",null,[o[9]||(o[9]=t("via: ",-1)),a(r,{href:"https://opensource.com/article/20/12/norka"},{default:e(()=>[...o[8]||(o[8]=[t("https://opensource.com/article/20/12/norka",-1)])]),_:1})]),n("p",null,[o[14]||(o[14]=t("作者：",-1)),a(r,{href:"https://opensource.com/users/seth"},{default:e(()=>[...o[10]||(o[10]=[t("Seth Kenlon",-1)])]),_:1}),o[15]||(o[15]=t(" 選題：",-1)),a(r,{href:"https://github.com/lujun9972"},{default:e(()=>[...o[11]||(o[11]=[t("lujun9972",-1)])]),_:1}),o[16]||(o[16]=t(" 譯者：",-1)),a(r,{href:"https://github.com/geekpi"},{default:e(()=>[...o[12]||(o[12]=[t("geekpi",-1)])]),_:1}),o[17]||(o[17]=t(" 校對：",-1)),a(r,{href:"https://github.com/wxy"},{default:e(()=>[...o[13]||(o[13]=[t("wxy",-1)])]),_:1})]),n("p",null,[o[20]||(o[20]=t("本文由 ",-1)),a(r,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...o[18]||(o[18]=[t("LCTT",-1)])]),_:1}),o[21]||(o[21]=t(" 原創編譯，",-1)),a(r,{href:"https://linux.cn/"},{default:e(()=>[...o[19]||(o[19]=[t("Linux中國",-1)])]),_:1}),o[22]||(o[22]=t(" 榮譽推出",-1))])])}const w=s(k,[["render",u]]);export{b as __pageData,w as default};
